    [Xunit.Fact]
    public static void TestGoldenMinimal() {
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        System.Text.StringBuilder compact = emon.Testport.NewText();
        System.Text.StringBuilder pretty = emon.Testport.NewText();
        emon.Testport.AssertEq(JtBuild(emon.Testport.TestFile("json/minimal.model"), nodes, attrs, regions, text, pages, ledger, st), 0, "the script builds");
        emon.Testport.AssertEq(Model.ModelCheck(nodes, attrs, regions, text, pages, ledger, st), 0, "the Model is well formed");
        Json.JsEmit(compact, 0, nodes, attrs, regions, text, pages, ledger);
        Json.JsEmit(pretty, 1, nodes, attrs, regions, text, pages, ledger);
        emon.Testport.AssertTextSpan(compact, emon.Testport.TestFile("json/minimal.json"), 0, JtEnd(emon.Testport.TestFile("json/minimal.json")), "compact", 0);
        emon.Testport.AssertTextSpan(pretty, emon.Testport.TestFile("json/minimal.pretty.json"), 0, JtEnd(emon.Testport.TestFile("json/minimal.pretty.json")), "pretty", 0);
    }
