        Json.JsCpt(t, 7250);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 7200);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, -5);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 0);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 12);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 10);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 5);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 99);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 100);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 101);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, 1234);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, -150);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, -100);
        emon.Port.TextAscii(t, " ");
        Json.JsCpt(t, -2147483648);
        emon.Port.TextAscii(t, " ");
